@(IsInternal=true)
string SERIAL_NUMBER;

@(PrimaryAssociation=true, IsInternal=true)
interface INTF_NAME;

@(DisplayName="Enable BPDU guard", Description="Enable spanning-tree bpduguard: true='enable', false='disable', no='return to default settings'")
enum BPDUGUARD_ENABLED {
validValues=true,false,no;
defaultValue=no;
};

@(DisplayName="Enable port type fast", Description="Enable spanning-tree edge port behavior")
boolean PORTTYPE_FAST_ENABLED {
defaultValue=true;
};

@(DisplayName="MTU", IsMTU=true, Description="MTU for the interface")
enum MTU {
validValues=default,jumbo;
defaultValue=jumbo;
};

@(DisplayName="Speed", Description="Interface speed")
enum SPEED {
validValues=Auto,10Mb,100Mb,1Gb,2.5Gb,5Gb,10Gb,25Gb,40Gb,50Gb,100Gb,200Gb,400Gb,800Gb;
defaultValue=Auto;
};

@(IsMandatory=false, DisplayName="Interface description", Description="Add description to the interface (max size 254)")
string DESC {
  minLength = 1;
  maxLength = 254;
};

@(IsMandatory=false, DisplayName="Enable CDP", Description="Enable CDP on the interface")
boolean CDP_ENABLE {
defaultValue=true;
};

@(IsMandatory=false, DisplayName="Disable LLDP transmit", Description="Disable LLDP transmit on the interface")
boolean lldpTransmit {
defaultValue=false;
};

@(IsMandatory=false, DisplayName="Disable LLDP receive", Description="Disable LLDP receive on the interface")
boolean lldpReceive {
defaultValue=false;
};

@(IsMandatory=false, DisplayName="Enable vPC orphan port", Description="If enabled, configure the interface as a vPC orphan port to be suspended by the secondary peer in vPC failures")
boolean ENABLE_ORPHAN_PORT {
defaultValue = false;
};

@(IsMandatory=false, Enum="auto,full,half", DisplayName="Port duplex mode", Description="Configure the port duplex mode")
string PORT_DUPLEX_MODE {
defaultValue=auto;
};

@(IsMandatory=false, IsMultiLineString=true, DisplayName="Freeform config", Description="Additional CLI for the interface. Note ! All configs should strictly match 'show run' output, with respect to case and newlines. Any mismatches will yield unexpected diffs during deploy.")
string CONF;

@(DisplayName="Enable interface", Description="Uncheck to disable the interface")
boolean ADMIN_STATE {
defaultValue=true;
};

@(IsMandatory=false,IsInternal=true)
boolean PTP {
defaultValue=false;
};

@(IsMandatory=true, DisplayName="PVLAN mode", Description="Private-VLAN mode", Section="PVLAN")
enum PVLAN_MODE {
validValues=promiscuous,trunk promiscuous,host,trunk secondary;
};

@(IsMandatory=false, IsShow="PVLAN_MODE!=promiscuous && PVLAN_MODE!=host", DisplayName="PVLAN allowed VLANs", Description="Allowed values: 'none', or VLAN ranges (ex: 1-200,500-2000,3000)", Section="PVLAN")
string PVLAN_ALLOWED_VLANS;

@(IsMandatory=false, IsShow="PVLAN_MODE!=promiscuous && PVLAN_MODE!=host", DisplayName="Native VLAN", Section="PVLAN", Description="Set native VLAN for the interface (min: 1, max: 4094)")
integer PVLAN_NATIVE_VLAN {
  min=1;
  max=4094;
};

@(IsMandatory=false, IsShow="PVLAN_MODE==promiscuous || PVLAN_MODE==trunk promiscuous", DisplayName="PVLAN mapping", Description="Private VLAN promiscuous mapping", Section="PVLAN")
struct ITEM {
  @(IsMandatory=true, DisplayName="Primary VLAN", Section="PVLAN")
  integer P_VLAN;
  @(IsMandatory=false, DisplayName="Secondary VLAN(s)", Section="PVLAN")
  string S_VLAN;
} MAPPING_LIST[];

@(IsMandatory=false, IsShow="PVLAN_MODE==host || PVLAN_MODE==trunk secondary", DisplayName="PVLAN association", Description="Private VLAN host association", Section="PVLAN")
struct ITEM {
  @(IsMandatory=true, DisplayName="Primary VLAN", Section="PVLAN")
  integer P_VLAN;
  @(IsMandatory=false, DisplayName="Secondary VLAN", Section="PVLAN")
  integer S_VLAN;
} ASSOCIATION_LIST[];

@(IsMandatory=false, DisplayName="Enable priority flow control", Section="QoS")
boolean ENABLE_PFC {
defaultValue = false;
};

@(IsMandatory=false, DisplayName="Enable QoS configuration", Description="Enable to configure a QoS policy for this interface. If AI queuing is enabled on the fabric, will use the QOS_CLASSIFICATION policy. Enter a custom policy below to override", Section="QoS")
boolean ENABLE_QOS {
defaultValue = false;
};

@(IsMandatory=false, IsShow="ENABLE_QOS==true", DisplayName="Custom QoS policy", Description="Custom QoS policy must be defined previously", Section="QoS")
string QOS_POLICY;

@(IsMandatory=false, DisplayName="Custom queuing policy ", Description="Queuing policy must be defined previously", Section="QoS")
string QUEUING_POLICY;

##
